create function public.treasury_october_plan_preview(p_batch uuid) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare b public.daily_base_batches%rowtype; item jsonb; existing jsonb; entities jsonb; output jsonb:='[]'; known jsonb; targets jsonb; suggestions jsonb; bank_name text; bank_count int; rev text;
begin
 perform public.treasury_require();
 select * into b from public.daily_base_batches where id=p_batch;
 if not found or not exists(select 1 from public.daily_base_rows where batch_id=p_batch and normalized_json->>'sourceProfile'='ERP-RAW-v1' and normalized_json->>'company'='SONACOL') then raise exception 'Selecciona una carga ERP de SONACOL.'; end if;
 entities:=public.erp_business_entities(p_batch);
 select coalesce(jsonb_agg(records.item order by records.item->>'id'),'[]') into existing from (
  select jsonb_build_object('id',m.id,'kind',case when m.normalized_json->>'category'='investment_placement' then 'placement' else 'commitment' end,
   'type',m.normalized_json->>'type','currency',m.normalized_json->>'currency','description',m.normalized_json->>'description',
   'date',coalesce(m.normalized_json->>'adjustedDate',m.normalized_json->>'reportDate',m.normalized_json->>'date'),'amount',m.normalized_json->'amount',
   'bankLedger',m.normalized_json->>'ledgerCode','deleted',m.deleted,'status',m.normalized_json->>'status','revision',m.revision,
   'executedAmount',coalesce(m.normalized_json->'executedAmount','0'::jsonb),'refs',coalesce(m.normalized_json->'planReferences','[]'),
   'legacy',m.normalized_json?'initialPlanKey' or m.normalized_json->>'legacySheet'='PROYEC',
   'reviewed',m.normalized_json->>'octoberTransition','linked',exists(select 1 from public.daily_forecast_links l where l.batch_id=p_batch and l.projection_id=m.id)) item
  from public.daily_manual m where m.batch_id=p_batch
  union all
  select jsonb_build_object('id',d.id,'kind',case when d.kind='redemption' then 'redemption' when d.kind='rule' then 'collection_rule' else 'collection' end,
   'type','income','currency',coalesce(d.values_json->>'currency','CLP'),'description',coalesce(d.values_json->>'description',d.values_json->>'note',d.target_key),
   'date',d.values_json->>'date','amount',d.values_json->'amount','bankLedger',d.values_json->>'bankLedger','deleted',d.deleted,
   'status',d.values_json->>'status','revision',d.revision,'executedAmount',public.treasury_execution_total(d.execution_json),
   'refs',d.plan_references,'targetKey',d.target_key,'values',d.values_json,'legacy',false,'linked',false) item
  from public.treasury_business_decisions d where d.batch_id=p_batch and (d.kind in ('redemption','adjustment') or (d.kind='rule' and d.values_json->>'ruleType'='collection'))
 ) records;
 for item in select value from jsonb_array_elements(public.sonacol_october_reference()) loop
  select count(*),min(normalized_json->>'bank') into bank_count,bank_name from public.daily_base_rows
   where batch_id=p_batch and normalized_json->>'recordRole'='bank_opening' and normalized_json->>'ledgerCode'=item->>'bankLedger' and normalized_json->>'currency'=item->>'currency';
  select coalesce(jsonb_agg(e->>'id'),'[]') into known from jsonb_array_elements(existing) e where e->'refs' ? (item->>'key');
  targets:='[]';
  if item->>'kind'='collection_rule' then
   if exists(select 1 from jsonb_array_elements(entities) e where e->>'kind'='invoice' and e->'normalized'->>'company'='SONACOL' and e->'normalized'->>'customerCode'=item->>'customerCode') then targets:=jsonb_build_array(item->>'customerCode'); end if;
  elsif item->>'kind'='collection' then
   select coalesce(jsonb_agg(e->'normalized'->>'businessKey'),'[]') into targets from jsonb_array_elements(entities) e
   where e->>'kind'='invoice' and e->'normalized'->>'company'='SONACOL' and e->'normalized'->>'customerCode'=item->>'customerCode'
    and e->'normalized'->>'document'=item->>'document' and e->'normalized'->>'currency'=item->>'currency'
    and round((e->'normalized'->>'amount')::numeric,2)=(item->>'amount')::numeric
    and e->'normalized'->>'issueDate'=item->>'issueDate' and e->'normalized'->>'dueDate'=item->>'dueDate';
  elsif item->>'kind'='redemption' then
   select coalesce(jsonb_agg(e->'normalized'->>'businessKey'),'[]') into targets from jsonb_array_elements(entities) e
   where e->>'kind'='investment' and e->'normalized'->>'company'='SONACOL' and e->'normalized'->>'currency'=item->>'currency'
    and e->'normalized'->>'ledgerCode'=item->>'positionLedger';
  end if;
  select coalesce(jsonb_agg(e->>'id'),'[]') into suggestions from jsonb_array_elements(existing) e where
   (item->>'kind' in ('collection','collection_rule') and e->>'kind'=item->>'kind' and targets ? (e->>'targetKey')) or
   (item->>'kind' not in ('collection','collection_rule') and e->>'kind'=item->>'kind' and e->>'currency'=item->>'currency' and e->>'type'=item->>'type'
    and (e->>'amount'=item->>'amount' or e->>'date'=item->>'date'));
  output:=output||jsonb_build_array(item||jsonb_build_object('bank',bank_name,'covered',bank_count=1,'known',known,'targets',targets,'suggestions',suggestions,'overdue',(item->>'date')::date<b.cutoff));
 end loop;
 rev:=md5(output::text||existing::text||entities::text||coalesce(public.daily_latest()::text,'')||p_batch::text||b.cutoff::text);
 return jsonb_build_object('revision',rev,'cutoff',b.cutoff,'canApply',p_batch=public.daily_latest(),'referenceDate','2026-10-09',
  'file','CAJA SONACOL v4 09-10-2026.xlsm','sha256','786e2b1282c6ca60c0c91de9aaa78225c6bd835011f99983524fc5a61d80be98',
  'rows',output,'existing',existing,'positions',coalesce((select jsonb_agg(e) from jsonb_array_elements(entities) e where e->>'kind'='investment'),'[]'),
  'invoices',coalesce((select jsonb_agg(e) from jsonb_array_elements(entities) e where e->>'kind'='invoice'),'[]'));
end; $$;

create function public.treasury_apply_october_plan(p_batch uuid,p_expected text,p_actions jsonb,p_prior jsonb default '{}') returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare preview jsonb; action jsonb; item jsonb; current_item jsonb; previous_item jsonb; n jsonb; saved jsonb; before_value jsonb;
 chosen_manual uuid; decision_id uuid; target text; old_manual public.daily_manual%rowtype; old_business public.treasury_business_decisions%rowtype;
 applied int:=0; reviewed int:=0; claims text[]:=array[]::text[]; used_ids text[]:=array[]::text[];
begin
 perform public.treasury_require(true); perform pg_advisory_xact_lock(728394107);
 preview:=public.treasury_october_plan_preview(p_batch);
 if not (preview->>'canApply')::boolean then raise exception 'Adopta el plan en la última carga ERP; las versiones anteriores se conservan.'; end if;
 if p_expected is distinct from preview->>'revision' then raise exception 'Cambió la planificación o la carga. Abre nuevamente la revisión.'; end if;
 if jsonb_typeof(p_actions) is distinct from 'array' or jsonb_array_length(p_actions) not between 1 and 103 or jsonb_typeof(p_prior) is distinct from 'object' then raise exception 'Selección de planificación inválida.'; end if;
 -- Resolve the previous active plan explicitly before incorporating any new commitment.
 if exists(select 1 from jsonb_array_elements(p_actions) a join lateral jsonb_array_elements(preview->'rows') r on r->>'key'=a->>'key' where r->>'kind'='commitment') then
  for previous_item in select e from jsonb_array_elements(preview->'existing') e where (e->>'legacy')::boolean and not (e->>'deleted')::boolean
   and e->>'status' not in ('borrador','cancelado') and nullif(e->>'reviewed','') is null and jsonb_array_length(e->'refs')=0 loop
   if exists(select 1 from jsonb_array_elements(p_actions) a where a->>'id'=previous_item->>'id') then continue; end if;
   if coalesce(p_prior->>(previous_item->>'id'),'') not in ('keep','retire') then raise exception 'Decide conservar o retirar cada compromiso anterior sin correspondencia.'; end if;
   if p_prior->>(previous_item->>'id')='retire' and (previous_item->>'linked')::boolean then raise exception 'Desvincula primero el compromiso anterior de su factura o inversión.'; end if;
   select * into old_manual from public.daily_manual where batch_id=p_batch and id=(previous_item->>'id')::uuid;
   update public.daily_manual set normalized_json=normalized_json||jsonb_build_object('octoberTransition',p_prior->>(previous_item->>'id'))
    ||case when p_prior->>(previous_item->>'id')='retire' then '{"status":"cancelado"}'::jsonb else '{}'::jsonb end,
    revision=revision+1,edited=true,updated_at=clock_timestamp(),updated_by=auth.uid() where batch_id=p_batch and id=old_manual.id;
   perform public.treasury_audit('Revisó compromiso anterior','Planificación',to_jsonb(old_manual),jsonb_build_object('id',old_manual.id,'action',p_prior->>(previous_item->>'id'),'reference','2026-10-09'));
   reviewed:=reviewed+1;
  end loop;
 end if;
 for action in select value from jsonb_array_elements(p_actions) loop
  select r into item from jsonb_array_elements(preview->'rows') r where r->>'key'=action->>'key';
  if item is null or coalesce(action->>'action','') not in ('new','keep','update') or jsonb_array_length(item->'known')>0
   or item->>'key'=any(claims) then raise exception 'Referencia inválida, repetida o ya incorporada.'; end if;
  claims:=array_append(claims,item->>'key');
  current_item:=null;
  if action->>'action'<>'new' then
   select e into current_item from jsonb_array_elements(preview->'existing') e where e->>'id'=action->>'id';
   if current_item is null or action->>'id'=any(used_ids) or jsonb_array_length(current_item->'refs')>0 then raise exception 'Selecciona un registro existente sin correspondencia de octubre; no puede usarse para dos referencias.'; end if;
   used_ids:=array_append(used_ids,action->>'id');
   if item->>'kind' in ('commitment','placement') then
    if current_item->>'kind' not in ('commitment','placement') or current_item->>'type' is distinct from item->>'type' or current_item->>'currency' is distinct from item->>'currency' then raise exception 'El compromiso debe tener el mismo tipo y moneda.'; end if;
   elsif current_item->>'kind' is distinct from item->>'kind' then raise exception 'La correspondencia no es del mismo tipo.'; end if;
   if action->>'action'='update' and (current_item->>'deleted')::boolean then raise exception 'El registro está eliminado. Conserva su eliminación; no se reactiva desde esta revisión.'; end if;
  elsif nullif(action->>'id','') is not null then raise exception 'Una incorporación nueva no debe indicar un registro existente.';
  end if;
  if action->>'action'<>'keep' and not (item->>'covered')::boolean then raise exception 'La cuenta bancaria de la referencia no está cubierta en su moneda.'; end if;
  if item->>'kind' in ('commitment','placement') then
   before_value:=null;
   if current_item is not null then select * into old_manual from public.daily_manual where batch_id=p_batch and id=(current_item->>'id')::uuid; before_value:=to_jsonb(old_manual); end if;
   if action->>'action'='keep' then chosen_manual:=old_manual.id;
   else
    if coalesce((current_item->>'linked')::boolean,false) then raise exception 'Desvincula primero la proyección relacionada; actualizarla podría duplicar o liberar su documento.'; end if;
    n:=jsonb_build_object('date',item->>'date','type',item->>'type','currency',item->>'currency','amount',item->'amount','category',item->>'category',
     'description',item->>'description','status',coalesce(current_item->>'status','proyectado'),'bank',item->>'bank','bankLedger',item->>'bankLedger');
    saved:=public.save_daily_manual(p_batch,case when current_item is null then null else (current_item->>'id')::uuid end,case when current_item is null then null else (current_item->>'revision')::int end,n,false);
    chosen_manual:=(saved->>'id')::uuid;
    -- Adoption explicitly replaces the operational date; notes, attachments and recurrence identity remain.
    update public.treasury_manual_details d set estimated_date=(item->>'date')::date,confirmed_date=null where d.batch_id=p_batch and d.manual_id=chosen_manual;
   end if;
   update public.daily_manual set normalized_json=normalized_json||jsonb_build_object('planReferences',coalesce(normalized_json->'planReferences','[]')||jsonb_build_array(item->>'key'),
    'octoberTransition','bound','planSource',item||jsonb_build_object('file',preview->>'file','sha256',preview->>'sha256')),
    revision=revision+1,edited=true,updated_at=clock_timestamp(),updated_by=auth.uid() where batch_id=p_batch and id=chosen_manual;
   saved:=jsonb_build_object('id',chosen_manual,'action',action->>'action','reference',item);
  else
   target:=nullif(action->>'target','');
   if item->>'kind' in ('collection','collection_rule') then
    target:=coalesce(target,current_item->>'targetKey');
    if target is null or not (item->'targets' ? target) then raise exception 'Selecciona el cliente o la factura coincidente en ERP. No se inventan documentos ni identidades.'; end if;
    if action->>'action'='new' and exists(select 1 from jsonb_array_elements(preview->'existing') e where e->>'kind'=item->>'kind' and e->>'targetKey'=target) then raise exception 'Ya existe una decisión para ese cliente o factura. Conserva o actualiza esa decisión, incluida su eliminación.'; end if;
    if current_item is not null and current_item->>'targetKey' is distinct from target then raise exception 'Selecciona la decisión del mismo cliente o factura.'; end if;
   elsif action->>'action'<>'keep' and (target is null or not (item->'targets' ? target)) then raise exception 'Selecciona explícitamente la posición ERP del rescate.'; end if;
   before_value:=null;
   if current_item is not null then select * into old_business from public.treasury_business_decisions where batch_id=p_batch and id=(current_item->>'id')::uuid; before_value:=to_jsonb(old_business); end if;
   if action->>'action'='keep' then decision_id:=old_business.id;
   else
    n:=coalesce(current_item->'values','{}');
    if item->>'kind'='redemption' then
     n:=n||jsonb_build_object('date',item->>'date','amount',item->'amount','currency',item->>'currency','bankLedger',item->>'bankLedger','bank',null,
      'description',item->>'description','status',coalesce(current_item->>'status','planned'));
    elsif item->>'kind'='collection_rule' then
     n:=n||jsonb_build_object('ruleType','collection','days',5,'bankLedger',item->>'bankLedger','bank',null,'priority',least(9999,1+coalesce((select max((values_json->>'priority')::int) from public.treasury_business_decisions where batch_id=p_batch and kind='rule' and not deleted and values_json->>'ruleType'='collection'),9)));
     if exists(select 1 from public.treasury_business_decisions where batch_id=p_batch and kind='rule' and not deleted and values_json->>'ruleType'='collection' and (values_json->>'priority')::int=9999) then raise exception 'No hay prioridad libre. Revisa las prioridades de las reglas existentes.'; end if;
    else
     n:=n||jsonb_build_object('bankLedger',item->>'bankLedger','bank',null);
     if nullif(item->>'overrideDate','') is not null then n:=n||jsonb_build_object('date',item->>'overrideDate'); end if;
     -- A formula-derived date stays a rule. Existing explicit dates are never erased here.
    end if;
    saved:=public.treasury_save_business(p_batch,case when current_item is null then null else (current_item->>'id')::uuid end,
     case when current_item is null then null else (current_item->>'revision')::int end,
     case when item->>'kind'='redemption' then 'redemption' when item->>'kind'='collection_rule' then 'rule' else 'adjustment' end,target,n,false);
    decision_id:=(saved->>'id')::uuid;
   end if;
   update public.treasury_business_decisions set plan_references=plan_references||jsonb_build_array(item->>'key'),revision=revision+1,updated_at=clock_timestamp(),updated_by=auth.uid() where batch_id=p_batch and id=decision_id;
   saved:=jsonb_build_object('id',decision_id,'action',action->>'action','reference',item,'target',target);
  end if;
  perform public.treasury_audit('Adoptó referencia de octubre','Planificación',before_value,saved||jsonb_build_object('batch',p_batch,'sourceFile',preview->>'file','sourceSha256',preview->>'sha256'));
  applied:=applied+1;
 end loop;
 return jsonb_build_object('applied',applied,'reviewed',reviewed);
end; $$;

-- Retire the obsolete entry point; old clients cannot add September's plan again.
alter function public.treasury_apply_initial_plan(uuid,text,jsonb,jsonb) rename to treasury_apply_initial_plan_before_october;
revoke all on function public.treasury_apply_initial_plan_before_october(uuid,text,jsonb,jsonb) from public,anon,authenticated;
create function public.treasury_apply_initial_plan(p_batch uuid,p_expected text,p_keys jsonb,p_bindings jsonb default '[]') returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.treasury_require(true);
 raise exception 'La referencia vigente es octubre de 2026. Actualiza la aplicación y abre Revisar transición del plan en Planificación.';
end; $$;
revoke all on function public.sonacol_october_reference() from public,anon,authenticated;
revoke all on function public.treasury_october_plan_preview(uuid),public.treasury_apply_october_plan(uuid,text,jsonb,jsonb),public.treasury_apply_initial_plan(uuid,text,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.treasury_october_plan_preview(uuid),public.treasury_apply_october_plan(uuid,text,jsonb,jsonb),public.treasury_apply_initial_plan(uuid,text,jsonb,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
